extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_scene("res://basket.tscn")
	if not check("basket", basket != null, "La scena basket.tscn deve aprirsi senza errori"):
		return

	if not check("fn_interval", has_function(basket, "get_spawn_interval"), "basket.gd deve avere una funzione get_spawn_interval()"):
		return

	basket.set("game_time", 0.0)
	var interval_0 = call_if_exists(basket, "get_spawn_interval")
	check("interval_at_0", typeof(interval_0) == TYPE_FLOAT and absf(interval_0 - 2.0) < 0.05, "All'inizio (tempo 0s) get_spawn_interval() deve restituire 2.0 secondi")

	basket.set("game_time", 30.0)
	var interval_30 = call_if_exists(basket, "get_spawn_interval")
	check("interval_at_30", typeof(interval_30) == TYPE_FLOAT and absf(interval_30 - 1.25) < 0.05, "A meta' percorso (tempo 30s) get_spawn_interval() deve restituire 1.25 secondi")

	basket.set("game_time", 60.0)
	var interval_60 = call_if_exists(basket, "get_spawn_interval")
	check("interval_at_60", typeof(interval_60) == TYPE_FLOAT and absf(interval_60 - 0.5) < 0.05, "A difficolta' massima (tempo 60s) get_spawn_interval() deve restituire 0.5 secondi")

	basket.set("game_time", 120.0)
	var interval_120 = call_if_exists(basket, "get_spawn_interval")
	check("interval_min", typeof(interval_120) == TYPE_FLOAT and absf(interval_120 - 0.5) < 0.05, "L'intervallo non deve scendere sotto 0.5 secondi anche con tempo avanzato")

	basket.set("spawn_timer", 1.8)
	call_if_exists(basket, "reset_game")
	var timer_reset = get_prop(basket, "spawn_timer", -1.0)
	check("reset_timer", timer_reset == 0.0, "reset_game() deve azzerare spawn_timer portandolo a 0.0")
